{"code": "note_finding = lambda msg, implication: print(f'⚠️ {msg}\n  Implication: {implication}')

# Check for missing values
if sales_df.isnull().sum().sum() > 0:
    note_finding('Missing values detected.', 'Must account for or drop them.')

# Check for duplicates
if sales_df.duplicated().sum() > 0:
    note_finding('Duplicate rows found.', 'Must drop duplicates to avoid bias.')

# Check for implausible values
if (sales_df['customer_age'] < 0).any():
    note_finding('Negative customer_age values detected.', 'These may be sentinel values; investigate.')

# Check if 'new' segment exists
if 'new' not in sales_df['customer_segment'].unique():
    note_finding('No customers in the "new" segment.', 'The question may be unanswerable.')

# Check if 'paid_search' channel exists
if 'paid_search' not in sales_df['channel'].unique():
    note_finding('No orders from "paid_search" channel.', 'The question may be unanswerable.')

# Check if 'converted' is binary
if not set(sales_df['converted'].unique()).issubset({0, 1}):
    note_finding('Converted column contains non-binary values.', 'Must verify coding or clean data.')"}
